594→            args.add(&tx.wallet_address)
595→                .map_err(|e| anyhow::anyhow!("{e}"))?;
596→            args.add(tx.timestamp).map_err(|e| anyhow::anyhow!("{e}"))?;
597→            args.add(&tx.tx_hash).map_err(|e| anyhow::anyhow!("{e}"))?;
598→            args.add(chain_str).map_err(|e| anyhow::anyhow!("{e}"))?;
599→            args.add(&tx.raw_metadata)
600→                .map_err(|e| anyhow::anyhow!("{e}"))?;
601→        }
602→        query.push_str(" ON CONFLICT (chain, tx_hash) DO NOTHING");
603→        sqlx::query_with(&query, args).execute(executor).await?;
604→        Ok(())
605→    }
606→
607→    pub async fn save_transactions_and_checkpoint(
608→        &self,
609→        txs: &[Transaction],
610→        checkpoint: &IndexerCheckpoint,
611→    ) -> anyhow::Result<()> {
612→        let mut db_tx = self.pool.begin().await?;
613→
614→        for chunk in txs.chunks(Self::BATCH_SIZE) {
615→            Self::save_transactions_with(&mut *db_tx, chunk).await?;
616→        }
617→        Self::save_checkpoint_with(&mut *db_tx, checkpoint).await?;
618→
619→        db_tx.commit().await?;
620→        Ok(())
621→    }
622→}
