        }
        query.push_str(&format!(
            "(${}, ${}, ${}, ${}, ${})",
            base + 1,
            base + 2,
            base + 3,
            base + 4,
            base + 5,
        ));
        use sqlx::Arguments;
        args.add(m.id).map_err(|e| anyhow::anyhow!("{e}"))?;
