    args.add(&cp.network).map_err(|e| anyhow::anyhow!("{e}"))?;
    args.add(&cp.source).map_err(|e| anyhow::anyhow!("{e}"))?;
    args.add(&cp.cursor).map_err(|e| anyhow::anyhow!("{e}"))?;
    args.add(cp.updated_at)
        .map_err(|e| anyhow::anyhow!("{e}"))?;
    Ok((query, args))
}

